package monadbft_test

// Cross-language conformance: every vector in testdata/vectors.txt was
// generated by the Rust monad-bft code (fixture-gen). The Go port must
// produce byte-identical encodings and equivalent signature behavior.

import (
	"bufio"
	"bytes"
	"encoding/hex"
	"os"
	"strings"
	"testing"

	"github.com/abhijitkrm/monadbft-go/crypto"
	"github.com/abhijitkrm/monadbft-go/cstypes"
	"github.com/abhijitkrm/monadbft-go/exec"
	"github.com/abhijitkrm/monadbft-go/messages"
	"github.com/abhijitkrm/monadbft-go/sigcol"
	"github.com/abhijitkrm/monadbft-go/testutil"
	"github.com/abhijitkrm/monadbft-go/types"
	"github.com/abhijitkrm/monadbft-go/validator"
	"github.com/zeebo/blake3"
)

func loadVectors(t *testing.T) map[string][]byte {
	t.Helper()
	f, err := os.Open("testdata/vectors.txt")
	if err != nil {
		t.Fatalf("open vectors: %v", err)
	}
	defer f.Close()
	out := map[string][]byte{}
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			continue
		}
		parts := strings.SplitN(line, ": ", 2)
		if len(parts) != 2 {
			t.Fatalf("bad vector line: %q", line)
		}
		b, err := hex.DecodeString(parts[1])
		if err != nil {
			t.Fatalf("bad hex for %s: %v", parts[0], err)
		}
		out[parts[0]] = b
	}
	return out
}

func TestBlake3(t *testing.T) {
	v := loadVectors(t)
	if got := blake3.Sum256([]byte("hello world")); !bytes.Equal(got[:], v["blake3_hello"]) {
		t.Fatalf("blake3 mismatch: got %x", got)
	}
}

func TestSecpSignRecover(t *testing.T) {
	v := loadVectors(t)
	kp := testutil.GetKey(22354)
	if got := kp.PubKey().Bytes(); !bytes.Equal(got, v["secp_pubkey_22354"]) {
		t.Fatalf("pubkey mismatch:\n got %x\nwant %x", got, v["secp_pubkey_22354"])
	}
	sig := kp.Sign(crypto.DomainConsensusMessage, []byte("hello world"))
	if !bytes.Equal(sig[:], v["secp_sig_hello"]) {
		t.Fatalf("sig mismatch:\n got %x\nwant %x", sig[:], v["secp_sig_hello"])
	}
	rec, err := sig.RecoverPubKey(crypto.DomainConsensusMessage, []byte("hello world"))
	if err != nil {
		t.Fatalf("recover: %v", err)
	}
	if !bytes.Equal(rec[:], v["secp_recovered_pubkey"]) {
		t.Fatalf("recovered pubkey mismatch")
	}
	if !sig.Verify(crypto.DomainConsensusMessage, []byte("hello world"), kp.PubKey()) {
		t.Fatal("verify failed")
	}
}

func TestBlsSignVerify(t *testing.T) {
	v := loadVectors(t)
	kp := testutil.GetCertKey(22354)
	if got := kp.PubKey().Compress(); !bytes.Equal(got, v["bls_pubkey_22354_compressed"]) {
		t.Fatalf("bls pubkey mismatch:\n got %x\nwant %x", got, v["bls_pubkey_22354_compressed"])
	}
	sig := kp.Sign(crypto.DomainVote, []byte("vote-msg"))
	if !bytes.Equal(sig.Compress(), v["bls_sig_vote_msg"]) {
		t.Fatalf("bls sig mismatch:\n got %x\nwant %x", sig.Compress(), v["bls_sig_vote_msg"])
	}
	if !sig.Verify(crypto.DomainVote, []byte("vote-msg"), kp.PubKey()) {
		t.Fatal("bls verify failed")
	}
}

func TestVoteRLP(t *testing.T) {
	v := loadVectors(t)
	vote := cstypes.Vote{
		ID:    types.BlockId{0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a, 0x2a},
		Round: 8,
		Epoch: 1,
	}
	if got := vote.EncodeRLP(nil); !bytes.Equal(got, v["vote_rlp"]) {
		t.Fatalf("vote rlp mismatch:\n got %x\nwant %x", got, v["vote_rlp"])
	}
	// decode round-trip
	var d cstypes.Vote
	if err := d.DecodeRLP(streamOf(v["vote_rlp"])); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if d != vote {
		t.Fatalf("round-trip mismatch")
	}
}

