func TestVoteMessageRLP(t *testing.T) {
	v := loadVectors(t)
	kp := testutil.GetCertKey(22354)
	vote := cstypes.Vote{
		ID:    bytes32(0x2a),
		Round: 8,
		Epoch: 1,
	}
	vm := messages.NewVoteMessage(vote, kp)
	if got := vm.EncodeRLP(nil); !bytes.Equal(got, v["vote_message_rlp"]) {
		t.Fatalf("vote message mismatch:\n got %x\nwant %x", got, v["vote_message_rlp"])
	}
	// verify sig against cert pubkey
	if !vm.Sig.Verify(crypto.DomainVote, vote.EncodeRLP(nil), kp.PubKey()) {
		t.Fatal("vote message sig verify failed")
	}
}

func TestTimeoutMessageRLP(t *testing.T) {
	v := loadVectors(t)
	kp := testutil.GetCertKey(22354)
	ti := cstypes.TimeoutInfo{Epoch: 12, Round: 123, HighQcRound: 0, HighTipRound: 0}
	tm := messages.NewTimeoutMessage(kp, ti, cstypes.HighExtendQc(cstypes.GenesisQC()), true, nil)
	if got := tm.EncodeRLP(nil); !bytes.Equal(got, v["timeout_message_rlp"]) {
		t.Fatalf("timeout message mismatch:\n got %x\nwant %x", got, v["timeout_message_rlp"])
	}
	// decode round-trip through the message layer
	var d messages.TimeoutMessage
	err := decodeExact(v["timeout_message_rlp"], func(s *streamT) error {
		return d.DecodeRLP(s, exec.Mock)
	})
	if err != nil {
		t.Fatalf("decode: %v", err)
	}
	if d.Timeout.TmInfo != ti {
		t.Fatalf("tminfo mismatch after decode")
	}
}

func TestSigCollection(t *testing.T) {
	v := loadVectors(t)
	// 4 validators; signers at insertion indices 0 and 2 → sorted positions
	// determined by compressed-pubkey ordering (fixture: bits {1,3} → 0x05).
	keys := make([]*crypto.BlsKeyPair, 4)
	nodes := make([]types.NodeId, 4)
	for i := range keys {
		keys[i] = testutil.GetCertKey(100 + uint64(i))
		nodes[i] = types.NewNodeId(testutil.GetKey(200 + uint64(i)).PubKey())
	}
	// sorted nodeids must match the fixture order
	sorted := append([]types.NodeId(nil), nodes...)
	sortNodeIds(sorted)
	for i := range sorted {
		if got := uncompressedPubkey(sorted[i].PubKey); !bytes.Equal(got, v["sorted_nodeid_"+itoa(i)]) {
			t.Fatalf("sorted nodeid %d mismatch:\n got %x\nwant %x", i, got, v["sorted_nodeid_"+itoa(i)])
		}
	}
	var entries []struct {
		NodeId     types.NodeId
		CertPubKey crypto.BlsPubKey
	}
	for i := range nodes {
		entries = append(entries, struct {
			NodeId     types.NodeId
			CertPubKey crypto.BlsPubKey
		}{nodes[i], keys[i].PubKey()})
	}
	mapping := validator.NewValidatorMapping(entries)

	vote := cstypes.Vote{ID: bytes32(0x2a), Round: 8, Epoch: 1}
	voteBytes := vote.EncodeRLP(nil)
	var sigs []sigcol.NodeSig
	for _, i := range []int{0, 2} {
		sigs = append(sigs, sigcol.NodeSig{
			NodeId: nodes[i],
			Sig:    keys[i].Sign(crypto.DomainVote, voteBytes),
		})
	}
	sc, err := sigcol.New(crypto.DomainVote, sigs, mapping, voteBytes)
	if err != nil {
		t.Fatalf("sigcol new: %v", err)
	}
	if got := sc.EncodeRLP(nil); !bytes.Equal(got, v["sig_collection_rlp"]) {
		t.Fatalf("sig collection mismatch:\n got %x\nwant %x", got, v["sig_collection_rlp"])
	}
	signers, err := sc.Verify(crypto.DomainVote, mapping, voteBytes)
	if err != nil {
		t.Fatalf("verify: %v", err)
	}
	if len(signers) != 2 {
		t.Fatalf("expected 2 signers, got %d", len(signers))
	}
}

func TestLeaderElection(t *testing.T) {
	v := loadVectors(t)
	// validators = get_key(300+i), stake = i+1; member order = sorted NodeId
	var vals []validator.ValidatorData
	nodes := map[[33]byte]types.NodeId{}
	for i := 0; i < 4; i++ {
		nid := types.NewNodeId(testutil.GetKey(300 + uint64(i)).PubKey())
		vals = append(vals, validator.ValidatorData{
			NodeId: nid,
			Stake:  types.StakeFromUint64(uint64(i + 1)),
		})
		nodes[[33]byte(nid.PubKey)] = nid
	}
	vs, err := validator.NewValidatorSet(vals)
	if err != nil {
		t.Fatal(err)
	}
	// verify member ordering matches Rust BTreeMap order
	for i, m := range vs.Members() {
		want := v["vs_member_"+itoa(i)]
		if !bytes.Equal(m.PubKey[:], want) {
			t.Fatalf("vs member %d: got %x want %x", i, m.PubKey, want)
		}
	}
	election := validator.WeightedRoundRobin{}
	for r := uint64(0); r < 8; r++ {
		got := election.GetLeader(types.Round(r), vs.Members(), func(id types.NodeId) types.Stake {
			s, _ := vs.StakeOf(id)
			return s
		})
		// fixture line: "leader_round_r: <pubkey> (pos N)"
		line := v["leader_round_"+itoa(int(r))+"_pk"]
		want := v["leader_round_"+itoa(int(r))]
		if line == nil && want == nil {
			t.Fatalf("missing vector for round %d", r)
		}
		if !bytes.Equal(got.PubKey[:], want) {
			t.Fatalf("round %d leader: got %x want %x", r, got.PubKey, want)
		}
	}
}

func TestConsensusMessageEnvelope(t *testing.T) {
	v := loadVectors(t)
	// rebuild the exact fixture: ConsensusMessage{version:1, Vote(vote)} signed
	// by get_key(42), where vote = {0x2a.., round 8, epoch 1}
	kp := testutil.GetKey(42)
	bk := testutil.GetCertKey(22354)
	vote := cstypes.Vote{ID: bytes32(0x2a), Round: 8, Epoch: 1}
	vm := messages.NewVoteMessage(vote, bk)
	cm := messages.ConsensusMessage{
		Version: 1,
		Message: messages.ProtocolMessage{Kind: messages.PMVote, Vote: &vm},
	}
	signed := messages.Sign(cm, kp)
	if got := signed.Message.EncodeRLP(nil); !bytes.Equal(got, v["consensus_msg_envelope_rlp"]) {
		t.Fatalf("envelope mismatch:\n got %x\nwant %x", got, v["consensus_msg_envelope_rlp"])
	}
	if !bytes.Equal(signed.Author.PubKey[:], v["consensus_msg_author"]) {
		t.Fatalf("author mismatch: got %x want %x", signed.Author.PubKey, v["consensus_msg_author"])
	}
	// decode + verify round trip
	var u messages.Unverified
	if err := decodeExact(v["consensus_msg_envelope_rlp"], func(s *streamT) error {
		return u.DecodeRLP(s, exec.Mock)
	}); err != nil {
		t.Fatalf("decode envelope: %v", err)
	}
	vf, err := u.Verify()
	if err != nil {
		t.Fatalf("verify: %v", err)
	}
	if vf.Author != signed.Author {
		t.Fatal("author mismatch after verify")
	}
	if vf.Message.Obj.Message.Kind != messages.PMVote {
		t.Fatal("wrong message kind")
	}
}
